export class ReplaceRowsOp extends EditOp {
  static readonly shorthandProperty: string | undefined = undefined;

  kind: string = "replace_rows";
  rows: PlanningRow[] = [];

  constructor(init?: Partial<ReplaceRowsOp>) {
    super(init);
    this.kind = init?.kind ?? "replace_rows";
    this.rows = init?.rows ?? [];
  }

  //#region Load Methods

  static load(
    data: Record<string, unknown>,
    context?: LoadContext,
  ): ReplaceRowsOp {
    context ??= new LoadContext();
    if (context) {
      data = context.processInput(data) as Record<string, unknown>;
    }

    const instance = new ReplaceRowsOp();

    if (data["kind"] !== undefined && data["kind"] !== null) {
      instance.kind = String(data["kind"]);
    }
    if (data["rows"] !== undefined && data["rows"] !== null) {
      instance.rows = ReplaceRowsOp.loadRows(
        data["rows"] as unknown[],
        context.at("rows"),
      );
    }

    if (context) {
      return context.processOutput(instance) as ReplaceRowsOp;
    }
    return instance;
  }

  static loadRows(
    data: Record<string, unknown>[] | unknown[],
    context?: LoadContext,
  ): PlanningRow[] {
    context ??= new LoadContext({ path: "rows" });
    if (!Array.isArray(data)) {
      const result: PlanningRow[] = [];
      for (const [k, v] of Object.entries(data)) {
        if (Array.isArray(v)) {
          throw new TypeError(
            context.at(k).path +
              ": invalid named collection entry category array",
          );
        }
        if (typeof v === "object" && v !== null && !Array.isArray(v)) {
          result.push(
            PlanningRow.load(
              { name: k, ...(v as Record<string, unknown>) },
              context.at(k),
            ),
          );
        } else {
          result.push(PlanningRow.load({ name: k, id: v }, context.at(k)));
        }
      }
      return result;
    }
    return data.map((item, index) =>
      PlanningRow.load(item as Record<string, unknown>, context.atIndex(index)),
    );
  }

  static saveRows(
    items: PlanningRow[],
    context?: SaveContext,
  ): Record<string, unknown>[] | Record<string, unknown> {
    if (!context) {
      context = new SaveContext();
    }

    // This type doesn't have a 'name' property, so always use array format
    return items.map((item) => item.save(context));
  }

  //#endregion

  //#region Save Methods

  save(context?: SaveContext): Record<string, unknown> {
    let obj: this = this;
    if (context) {
      obj = context.processObject(obj) as this;
    }

    // Start with parent class properties
    const result = super.save(context);

    if (obj.kind !== undefined && obj.kind !== null) {
      result["kind"] = obj.kind;
    }
    if (obj.rows !== undefined && obj.rows !== null) {
      result["rows"] = ReplaceRowsOp.saveRows(obj.rows, context);
    }
    return result;
  }

  toYaml(context?: SaveContext): string {
    context = context ?? new SaveContext();
    return context.toYaml(this.save(context));
  }

  toJson(context?: SaveContext, indent: number = 2): string {
    context = context ?? new SaveContext();
    return context.toJson(this.save(context), indent);
  }

  static fromJson(json: string, context?: LoadContext): ReplaceRowsOp {
    const data = JSON.parse(json);
    return ReplaceRowsOp.load(data as Record<string, unknown>, context);
  }

  static fromYaml(yaml: string, context?: LoadContext): ReplaceRowsOp {
    const data = LoadContext.parseYaml(yaml);
    return ReplaceRowsOp.load(data as Record<string, unknown>, context);
  }

  //#endregion
}

